/**
 * GENERATED by build.py - edit DOMAIN_CONNECTED in build.py, not this file.
 * - bobbyacservices.com (no www)  -> 301 to https://www.bobbyacservices.com (same path)
 * - bobbyacservices.pages.dev     -> 301 to https://www.bobbyacservices.com only when the domain is connected
 * - branch previews (*.bobbyacservices.pages.dev) are left alone.
 */
const CANONICAL_HOST = 'www.bobbyacservices.com';
const REDIRECT_PAGES_DEV = false;

export async function onRequest(context) {
  const url = new URL(context.request.url);
  const host = url.hostname;
  if (host === 'bobbyacservices.com' || (REDIRECT_PAGES_DEV && host === 'bobbyacservices.pages.dev')) {
    url.hostname = CANONICAL_HOST;
    url.protocol = 'https:';
    url.port = '';
    return Response.redirect(url.toString(), 301);
  }
  return context.next();
}
